# Fix research: use visit instead of enter for query checking
old_research_body = '''    def _enter(path, key, value):
        try:
            if query(path, key, value):
                ret.append((path + (key,), value))
        except Exception:
            if reraise:
                raise
        return enter(path, key, value)

    remap(root, enter=_enter, cache=cache)'''

new_research_body = '''    def _visit(path, key, value):
        try:
            if query(path, key, value):
                ret.append((path + (key,), value))
        except Exception:
            if reraise:
                raise
        return (key, value)

    remap(root, visit=_visit, cache=cache)'''

